def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def mod_sum(subseq):
        return sum(subseq) % m

    def is_good(subseq):
        if not subseq:
            return False
        total = sum(subseq)
        if total % m != 0:
            return False
        # Check all non-empty subsequences of this subsequence
        from itertools import combinations
        for r in range(1, len(subseq) + 1):
            for combo in combinations(subseq, r):
                sub_sum = sum(combo)
                if sub_sum % m != 0:
                    return False
        return True

    count = 0
    # Iterate over all non-empty subsequences
    for mask in range(1, 1 << n):
        subseq = []
        for i in range(n):
            if mask & (1 << i):
                subseq.append(a[i])

        if is_good(subseq):
            count += 1

    return count

t = int(input())
for _ in range(t):
    print(solve())
